def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def add_result(name: str, status: str) -> None:
        if name:
            results[name] = status

    def clean_xml(text: str) -> str:
        # Remove control chars invalid in XML 1.0
        return re.sub(r"[\x00-\x08\x0B\x0C\x0E-\x1F]", "", text)

    def local_tag(tag: str) -> str:
        return tag.split("}")[-1] if tag else tag

    # ---- XML parsing ----
    fragments = re.findall(r"(<testsuites[\s\S]*?</testsuites>)", log)
    if not fragments:
        suites = re.findall(r"(<testsuite[\s\S]*?</testsuite>)", log)
        fragments = [f"<testsuites>{frag}</testsuites>" for frag in suites]

    for frag in fragments:
        frag = clean_xml(frag)
        try:
            root = ET.fromstring(frag)
        except ET.ParseError:
            try:
                root = ET.fromstring(f"<testsuites>{frag}</testsuites>")
            except ET.ParseError:
                continue

        for testcase in root.iter():
            if local_tag(testcase.tag) != "testcase":
                continue
            name = testcase.get("name", "") or ""
            classname = testcase.get("classname", "") or ""
            test_name = f"{classname}.{name}" if classname else name

            status = "pass"
            for child in testcase:
                tag = local_tag(child.tag)
                if tag in ("failure", "error"):
                    status = "fail"
                    break
                if tag == "skipped":
                    status = "skip"
            add_result(test_name, status)

    # ---- Line-based fallbacks (pytest/unittest/jest/go) ----
    for m in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", log, re.MULTILINE):
        state = m.group(2)
        status = "pass" if state == "PASSED" else "skip" if state == "SKIPPED" else "fail"
        add_result(m.group(1), status)

    for m in re.finditer(r"^(\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", log, re.MULTILINE):
        state = m.group(2)
        status = "pass" if state == "ok" else "skip" if state == "skipped" else "fail"
        add_result(m.group(1), status)

    for m in re.finditer(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", log, re.MULTILINE):
        state = m.group(1)
        status = "pass" if state == "PASS" else "skip" if state == "SKIP" else "fail"
        add_result(m.group(2), status)

    for m in re.finditer(r"^[\s]*([✓✕○])\s+(.+?)\s*$", log, re.MULTILINE):
        sym = m.group(1)
        status = "pass" if sym == "✓" else "skip" if sym == "○" else "fail"
        add_result(m.group(2), status)

    return results
